xpath.script:
(function () {
    var p = window.location.pathname;
    if (p === '/my/training' || p.startsWith('/my/training/')) {
        try {
            if (window.self !== window.top) {
                document.documentElement.classList.add('lms-iframe-mode');
            }
        } catch (e) {
            document.documentElement.classList.add('lms-iframe-mode');
        }
    }
})();

body.script:
(function () {
    'use strict';

    // Read config from data attributes (safe regardless of QWeb rendering mode)
    var cfg = document.getElementById('scorm-config');
    var RECORD_ID    = parseInt(cfg.dataset.recordId, 10);
    var PASSING_SCORE = parseFloat(cfg.dataset.passingScore) || 80;

    var cmiData = {};
    var scormInitialized = false;
    var scormFinished    = false;

    function postProgress(data) {
        var xhr = new XMLHttpRequest();
        xhr.open('POST', '/lms/scorm/' + RECORD_ID + '/commit', true);
        xhr.setRequestHeader('Content-Type', 'application/json');
        xhr.send(JSON.stringify(data));
    }

    // ── SCORM 1.2 API ──────────────────────────────────────────────
    var API = {
        LMSInitialize: function (s) {
            scormInitialized = true;
            postProgress({ action: 'initialize', cmi: cmiData });
            return 'true';
        },
        LMSFinish: function (s) {
            scormFinished = true;
            postProgress({ action: 'finish', cmi: cmiData });
            return 'true';
        },
        LMSGetValue: function (key) {
            return cmiData[key] !== undefined ? String(cmiData[key]) : '';
        },
        LMSSetValue: function (key, value) {
            cmiData[key] = value;
            if (key === 'cmi.core.lesson_status' ||
                    key === 'cmi.completion_status' ||
                    key === 'cmi.score.raw') {
                postProgress({ action: 'set', key: key, value: value, cmi: cmiData });
            }
            return 'true';
        },
        LMSCommit: function (s) {
            postProgress({ action: 'commit', cmi: cmiData });
            return 'true';
        },
        LMSGetLastError:   function () { return '0'; },
        LMSGetErrorString: function (e) { return ''; },
        LMSGetDiagnostic:  function (e) { return ''; }
    };

    // ── SCORM 2004 API ─────────────────────────────────────────────
    var API_1484_11 = {
        Initialize:     function (s) { return API.LMSInitialize(s); },
        Terminate:      function (s) { return API.LMSFinish(s); },
        GetValue:       function (k) { return API.LMSGetValue(k); },
        SetValue:       function (k, v) { return API.LMSSetValue(k, v); },
        Commit:         function (s) { return API.LMSCommit(s); },
        GetLastError:   function () { return '0'; },
        GetErrorString: function (e) { return ''; },
        GetDiagnostic:  function (e) { return ''; }
    };

    // Expose on this wrapper window so standard parent-chain lookup works
    window.API        = API;
    window.API_1484_11 = API_1484_11;

    // ── Wire up content frame ──────────────────────────────────────
    var frame = document.getElementById('scorm-content-frame');
    frame.addEventListener('load', function () {
        document.getElementById('scorm-loading').style.display = 'none';
        frame.style.display = 'block';

        // Also inject API directly onto the content window.
        // Belt-and-suspenders: covers SCORM packages that look for
        // window.API on their own window rather than walking parent chain.
        try {
            frame.contentWindow.API        = API;
            frame.contentWindow.API_1484_11 = API_1484_11;
        } catch (e) { /* cross-origin guard — should never fire */ }
    });

    window.addEventListener('beforeunload', function () {
        if (scormInitialized && !scormFinished) {
            postProgress({ action: 'unload', cmi: cmiData });
        }
    });
})();

